let maReferenceTurn=0,maReferenceURL=null,maReferencePdf=null,maReferencePageTurn=0;
function maReleaseReferenceURL(){maReferencePageTurn++;if(maReferencePdf){maReferencePdf.destroy().catch(()=>{});maReferencePdf=null}if(maReferenceURL){URL.revokeObjectURL(maReferenceURL);maReferenceURL=null}}
