function maOpenAssessmentDocuments(group,selectedId){const d=maCurrent(),docs=maAssessmentDocuments(d,group);if(!docs.length)return;const name=MA_ASSESSMENT_GROUPS.find(g=>g.id===group)?.name||group;maReferenceTurn++;maReleaseReferenceURL();showDrawer('Tài liệu đối chiếu · '+name,`<div class="ma-reference-viewer" id="maReferenceViewer" data-group="${group}"><aside class="ma-reference-file-list" aria-label="Tài liệu ${esc(name)}">${docs.map(doc=>`<button type="button" data-reference-id="${doc.id}" onclick="maSelectReferenceDocument('${doc.id}')"><strong>${esc(doc.name)}</strong><small>${esc(d.checks.find(c=>c.id===doc.checkId)?.title||'')}</small></button>`).join('')}</aside><div class="ma-reference-preview" id="maReferencePreview" aria-live="polite"></div></div>`,btn('Đóng','onclick="closeDrawer()"'));$('#overlay .drawer').classList.add('ma-reference-drawer');maSelectReferenceDocument(docs.some(doc=>doc.id===selectedId)?selectedId:docs[0].id)}
async function maSelectReferenceDocument(id){const viewer=$('#maReferenceViewer');if(!viewer)return;const d=maCurrent(),doc=maAssessmentDocuments(d,viewer.dataset.group).find(doc=>doc.id===id);if(!doc)return;const turn=++maReferenceTurn;maReleaseReferenceURL();viewer.querySelectorAll('[data-reference-id]').forEach(button=>{button.classList.toggle('selected',button.dataset.referenceId===id);button.setAttribute('aria-pressed',String(button.dataset.referenceId===id))});const preview=$('#maReferencePreview');preview.innerHTML='<p class="ma-reference-loading" role="status">Đang mở tài liệu…</p>';let original=null;try{if(doc.attachmentId)original=await attachmentRequest('readonly',store=>store.get(doc.attachmentId))}catch{}if(turn!==maReferenceTurn||!viewer.isConnected)return;const file=original?.file,isPdf=file&&(file.type==='application/pdf'||/\.pdf$/i.test(file.name)),isImage=file&&/^image\/(png|jpeg|webp|gif)$/.test(file.type);let content='';if(isPdf||isImage){maReferenceURL=URL.createObjectURL(file);content=isPdf?`<div class="ma-reference-pdf-controls" id="maReferencePdfControls"></div><div class="ma-reference-pdf-pages" id="maReferencePdfPages"><p class="ma-reference-loading">Đang tải PDF…</p></div>`:`<div class="ma-reference-image"><img src="${maReferenceURL}" alt="${esc(doc.name)}"></div>`}else{let text=(doc.pages||[]).map(page=>(doc.pages.length>1?'Trang '+page.page+'\n':'')+page.text).join('\n\n');if(file&&(/\.txt$/i.test(file.name)||file.type==='text/plain'))text=await file.text();if(turn!==maReferenceTurn||!viewer.isConnected)return;content=`<pre class="ma-reference-text">${esc(text||'Tệp chưa có nội dung xem trước. Chọn Tải tệp gốc để mở bằng ứng dụng phù hợp.')}</pre>`}preview.innerHTML=`<div class="ma-reference-preview-head"><strong>${esc(doc.name)}</strong><div class="actions">${isPdf?`<a class="btn small" href="${maReferenceURL}" target="_blank" rel="noopener noreferrer">Mở tab mới</a>`:''}${file?`<button type="button" class="btn small" onclick="downloadScannedOriginal('${doc.attachmentId}')">${icon('download')} Tải tệp gốc</button>`:''}</div></div>${content}`;if(isPdf)maRenderReferencePDF(file,turn)}
async function maRenderReferencePDF(file,turn){try{const lib=await loadOCRScript('https://cdn.jsdelivr.net/npm/pdfjs-dist@3.11.174/build/pdf.min.js','pdfjsLib');if(turn!==maReferenceTurn||!$('#maReferencePdfPages'))return;lib.GlobalWorkerOptions.workerSrc='https://cdn.jsdelivr.net/npm/pdfjs-dist@3.11.174/build/pdf.worker.min.js';const pdf=await lib.getDocument({data:new Uint8Array(await file.arrayBuffer()),isEvalSupported:false,useSystemFonts:true}).promise;if(turn!==maReferenceTurn||!$('#maReferencePdfPages')){await pdf.destroy();return}maReferencePdf=pdf;await maRenderReferencePage(1)}catch{if(turn===maReferenceTurn&&$('#maReferencePdfPages'))$('#maReferencePdfPages').innerHTML='<p class="ma-reference-loading">Chưa tải được trình xem PDF. Chọn Mở tab mới hoặc Tải tệp gốc để xem tài liệu.</p>'}}
async function maRenderReferencePage(value){const pdf=maReferencePdf,container=$('#maReferencePdfPages');if(!pdf||!container)return;const page=Math.max(1,Math.min(pdf.numPages,Number(value)||1)),turn=++maReferencePageTurn;$('#maReferencePdfControls').innerHTML=`<button type="button" class="btn small" aria-label="Trang PDF trước" ${page===1?'disabled':''} onclick="maRenderReferencePage(${page-1})">‹</button><label>Trang <select class="select" id="maReferencePdfPage" onchange="maRenderReferencePage(this.value)">${Array.from({length:pdf.numPages},(_,i)=>`<option value="${i+1}" ${i+1===page?'selected':''}>${i+1} / ${pdf.numPages}</option>`).join('')}</select></label><button type="button" class="btn small" aria-label="Trang PDF sau" ${page===pdf.numPages?'disabled':''} onclick="maRenderReferencePage(${page+1})">›</button>`;try{const source=await pdf.getPage(page);if(turn!==maReferencePageTurn||!container.isConnected)return;const base=source.getViewport({scale:1}),scale=Math.min(2,Math.max(.3,(container.clientWidth-32)/base.width)),viewport=source.getViewport({scale}),ratio=Math.min(window.devicePixelRatio||1,2),canvas=document.createElement('canvas');canvas.className='ma-reference-pdf-canvas';canvas.setAttribute('aria-label','Trang '+page+' của tài liệu PDF');canvas.width=Math.ceil(viewport.width*ratio);canvas.height=Math.ceil(viewport.height*ratio);canvas.style.width=viewport.width+'px';canvas.style.height=viewport.height+'px';container.replaceChildren(canvas);await source.render({canvasContext:canvas.getContext('2d'),viewport,transform:ratio===1?null:[ratio,0,0,ratio,0,0]}).promise;if(turn===maReferencePageTurn&&container.isConnected){canvas.dataset.rendered='true';container.scrollTop=0}}catch{if(turn===maReferencePageTurn&&container.isConnected)container.innerHTML='<p class="ma-reference-loading">Không hiển thị được trang PDF. Bạn có thể mở tab mới để xem bản gốc.</p>'}}
function maAssessmentItemRow(item={},group='general',index=0){const name=MA_ASSESSMENT_GROUPS.find(g=>g.id===group)?.name||'';return `<article class="ma-assessment-item ma-assessment-entry" data-item-id="${esc(item.id||'')}"><header class="ma-assessment-entry-head"><strong>Hạng mục <span class="ma-assessment-item-number">${String(index+1).padStart(2,'0')}</span> </strong><button class="btn ghost small" type="button" aria-label="Xóa hạng mục đánh giá" onclick="maRemoveAssessmentItem(this)">${icon('close')} Xóa</button></header><div class="ma-assessment-entry-grid"><label class="ma-assessment-entry-field full"><span>Tên hạng mục <span class="required-mark">*</span></span><input data-column="title" aria-label="Hạng mục ${index+1} — ${esc(name)}" value="${esc(item.title||'')}" maxlength="250" placeholder="Nhập tên hạng mục cần đánh giá"></label><label class="ma-assessment-entry-field full"><span>Nội dung</span><textarea data-column="content" aria-label="Nội dung ${index+1} — ${esc(name)}" rows="3" maxlength="10000" placeholder="Mô tả hiện trạng, thông tin và hồ sơ liên quan">${esc(item.content||'')}</textarea></label><label class="ma-assessment-entry-field"><span>Ý kiến pháp lý</span><textarea data-column="legalOpinion" aria-label="Ý kiến pháp lý ${index+1} — ${esc(name)}" rows="4" maxlength="10000" placeholder="Nhập nhận định, căn cứ và ý kiến pháp lý">${esc(item.legalOpinion||'')}</textarea></label><label class="ma-assessment-entry-field"><span>Đề xuất</span><textarea data-column="proposal" aria-label="Đề xuất ${index+1} — ${esc(name)}" rows="4" maxlength="10000" placeholder="Nhập phương án, kiến nghị hoặc nội dung cần bổ sung">${esc(item.proposal||'')}</textarea></label></div></article>`}
function maRenumberAssessmentItems(container){container.querySelectorAll('.ma-assessment-item').forEach((row,i)=>{row.querySelector('.ma-assessment-item-number').textContent=String(i+1).padStart(2,'0');row.querySelectorAll('[data-column]').forEach(field=>{const labels={title:'Hạng mục',content:'Nội dung',legalOpinion:'Ý kiến pháp lý',proposal:'Đề xuất'};field.setAttribute('aria-label',labels[field.dataset.column]+' '+(i+1)+' — '+MA_ASSESSMENT_GROUPS.find(g=>g.id===container.dataset.assessmentGroup).name)})})}
function maRemoveAssessmentItem(button){if(!maEditable())return;const row=button.closest('.ma-assessment-item'),body=row.parentElement;row.remove();maRenumberAssessmentItems(body);maRefreshSectionStatus('assessment')}
function maAddAssessmentItem(id){if(!maEditable()||!maClassificationComplete(maCurrent()))return;const container=$('#maAssessmentItems-'+id),index=container.querySelectorAll('.ma-assessment-item').length;container.insertAdjacentHTML('beforeend',maAssessmentItemRow({},id,index));container.lastElementChild.querySelector('[data-column=title]').focus()}
function maSectionValues(type,d=maCurrent(),fromForm=false){const clean=(items,keys)=>items.map(item=>keys.map(k=>(item[k]||'').trim())).filter(values=>values.some(Boolean));if(type==='assessment')return MA_ASSESSMENT_GROUPS.map(g=>{let items=maGetAssessment(d,g.id).items;if(fromForm){const box=document.getElementById('maAssessmentItems-'+g.id);if(box)items=[...box.querySelectorAll('.ma-assessment-item')].map(row=>Object.fromEntries([...row.querySelectorAll('[data-column]')].map(el=>[el.dataset.column,el.value])))}return clean(items,['title','content','legalOpinion','proposal'])});const keys=type==='risk'?['title','cause','action']:['title','duration','note'];let items=d[type==='risk'?'risks':'roadmap'].map(r=>type==='roadmap'?{...r,note:maRoadmapNote(r)}:r);if(fromForm&&document.getElementById('maTemplate-'+type))items=maReadTemplate(type,d).rows;return clean(items,keys)}
function maSectionSaveState(type,d=maCurrent(),dirty=false){if(dirty)return {kind:'dirty',text:'Có thay đổi chưa lưu'};const draft=type==='assessment'?MA_ASSESSMENT_GROUPS.some(g=>maGetAssessment(d,g.id).items.some(item=>item.aiDraft)):d[type==='risk'?'risks':'roadmap'].some(item=>item.aiDraft);if(draft)return {kind:'dirty',text:'Chưa lưu'};const historyPattern=type==='assessment'?/^Lưu (?:bảng thẩm định|đánh giá thẩm định)/:type==='risk'?/^Lưu đánh giá rủi ro/:/^Lưu (?:lộ trình|đánh giá rủi ro pháp lý và lộ trình)/;const time=d.sectionSavedAt?.[type]||d.history?.find(entry=>historyPattern.test(entry.text||''))?.time;if(time){const date=new Date(time);if(!Number.isNaN(date.getTime())){const parts=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Bangkok',day:'2-digit',month:'2-digit',year:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(date);const part=key=>parts.find(p=>p.type===key)?.value;return {kind:'saved',text:`Dữ liệu lúc ${part('day')}/${part('month')}/${part('year')} ${part('hour')}:${part('minute')}`}}}const has=maSectionValues(type,d).flat(2).some(Boolean);return {kind:has?'saved':'empty',text:has?'Dữ liệu lúc —':'Chưa lưu'}}

function maSaveStatus(type,d=maCurrent()){const state=maSectionSaveState(type,d);return `<span class="ma-save-status ${state.kind}" data-save-status="${type}" role="status" aria-live="polite">${esc(state.text)}</span>`}
function maRefreshSectionStatus(type,failed=false){const el=document.querySelector('[data-save-status="'+type+'"]');if(!el||!maCurrent())return;const dirty=JSON.stringify(maSectionValues(type,maCurrent(),true))!==JSON.stringify(maSectionValues(type));const state=failed?{kind:'error',text:'Lưu chưa thành công — vui lòng thử lại'}:maSectionSaveState(type,maCurrent(),dirty);el.textContent=state.text;el.className='ma-save-status '+state.kind}
function maSaveStatusInput(event){const form=event.target.closest('form');const type=form?.id==='maAssessmentTableForm'?'assessment':form?.id==='maSection-risk'?'risk':form?.id==='maSection-roadmap'?'roadmap':null;if(type)maRefreshSectionStatus(type)}
document.addEventListener('input',maSaveStatusInput);document.addEventListener('change',maSaveStatusInput);

function maAnalysis(){const d=maCurrent(),locked=maLocked()||!maClassificationComplete(d);return maPanel('Đánh giá thẩm định',`<form id="maAssessmentTableForm" class="ma-assessment-editor" onsubmit="maSaveAssessmentTable(event)"><fieldset class="ma-assessment-fieldset" ${locked?'disabled':''}>${MA_ASSESSMENT_GROUPS.map((g,gi)=>{const a=maGetAssessment(d,g.id);return `<details class="ma-assessment-form-group" data-assessment-section="${g.id}" ${gi===0?'open':''}><summary><span class="ma-assessment-group-number">${gi+1}</span><strong>${g.name}</strong><span class="ma-group-document-count">${maAssessmentDocuments(d,g.id).length} tài liệu</span><svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="m6 9 6 6 6-6"/></svg></summary><div class="ma-assessment-form-group-body">${maAssessmentReferences(d,g.id)}<div id="maAssessmentItems-${g.id}" class="ma-assessment-entry-list" data-assessment-group="${g.id}">${(a.items.length?a.items:[{}]).map((item,i)=>maAssessmentItemRow(item,g.id,i)).join('')}</div><button class="btn ma-assessment-add" type="button" onclick="maAddAssessmentItem('${g.id}')">${icon('plus')} Thêm hạng mục</button>${a.findings?`<details class="ma-assessment-legacy"><summary>Nhận định chung đã lưu trước đây</summary><p>${esc(a.findings)}</p></details>`:''}</div></details>`}).join('')}<p class="user-error" id="maAssessmentTableError" role="alert"></p></fieldset></form>`,`${maSaveStatus('assessment',d)}<button class="btn primary" type="submit" form="maAssessmentTableForm" ${locked?'disabled':''}>Lưu</button>`)}
function maSaveAssessment(){return maSaveAssessmentTable()}
function maSaveAssessmentTable(event){
 event?.preventDefault();if(!maEditable())return;const d=maCurrent();if(!maClassificationComplete(d)){toast('Hoàn tất phân loại hồ sơ trước khi đánh giá.');return}
 const form=$('#maAssessmentTableForm');if(!form.reportValidity())return;const changes={};
 for(const group of MA_ASSESSMENT_GROUPS){const items=[];for(const [i,row] of [...$('#maAssessmentItems-'+group.id).querySelectorAll('.ma-assessment-item')].entries()){const values=Object.fromEntries([...row.querySelectorAll('[data-column]')].map(field=>[field.dataset.column,field.value.trim()]));if(!Object.values(values).some(Boolean))continue;if(!values.title){$('#maAssessmentTableError').textContent='Vui lòng nhập hạng mục ở nhóm '+group.name+', dòng '+(i+1)+'.';row.closest('.ma-assessment-form-group').open=true;row.querySelector('[data-column=title]').focus();return}items.push({...maGetAssessment(d,group.id).items.find(item=>item.id===row.dataset.itemId),id:row.dataset.itemId||'assessment-'+group.id+'-'+Date.now()+'-'+i,...values,aiDraft:false})}changes[group.id]={...maGetAssessment(d,group.id),schemaVersion:3,items}}
 const opened=[...document.querySelectorAll('.ma-assessment-form-group[open]')].map(el=>el.dataset.assessmentSection);
 const key=d.projectCode+'/'+d.stage,next=JSON.parse(JSON.stringify(maData)),target=next[key];target.reviewStarted=target.reviewStarted||new Date().toISOString();Object.assign(target.assessments,changes);target.report=null;target.analysisCompleted=maAssessmentFinished(target)?new Date().toISOString():null;target.sectionSavedAt={...target.sectionSavedAt,assessment:new Date().toISOString()};target.history.unshift({text:'Lưu đánh giá thẩm định pháp lý dự án',time:new Date().toISOString()});const saved=maSaveData(next);if(saved){for(const g of MA_ASSESSMENT_GROUPS){let i=0;document.querySelectorAll('#maAssessmentItems-'+g.id+' .ma-assessment-item').forEach(row=>{if([...row.querySelectorAll('[data-column]')].some(el=>el.value.trim()))row.dataset.itemId=changes[g.id].items[i++].id})}document.querySelectorAll('.ma-assessment-form-group').forEach(el=>el.open=opened.includes(el.dataset.assessmentSection));maRefreshSectionStatus('assessment');toast('Đã lưu đánh giá thẩm định.');}else maRefreshSectionStatus('assessment',true)
}
function maRoadmapNote(r){return r.note??[r.dependency&&'Điều kiện / phụ thuộc: '+r.dependency,r.cost&&'Chi phí: '+r.cost,r.owner&&'Phụ trách: '+r.owner].filter(Boolean).join('\n')}
function maTemplateRow(type,r={},index=0){const fields=type==='risk'?[['title','Mô tả rủi ro',r.title],['cause','Nguyên nhân',r.cause],['action','Phương án xử lý',r.action]]:[['title','Công việc',r.title],['duration','Thời gian dự kiến',r.duration],['note','Ghi chú',maRoadmapNote(r)]];return `<article class="ma-assessment-entry" data-template-row data-source-index="${index}"><header class="ma-assessment-entry-head"><strong>${type==='risk'?'Rủi ro':'Công việc'} <span class="ma-template-number">${String(index+1).padStart(2,'0')}</span> </strong><button type="button" class="btn ghost small" aria-label="Xóa dòng" onclick="maRemoveTemplateRow(this)" ${maLocked()?'disabled':''}>${icon('close')} Xóa</button></header><div class="ma-assessment-entry-grid">${fields.map(([key,label,value],i)=>`<label class="ma-assessment-entry-field ${i===0?'full':''}"><span>${label}</span><textarea data-field="${key}" aria-label="${label}" rows="${i===0?3:4}" placeholder="Nhập ${label.toLowerCase()}">${esc(value||'')}</textarea></label>`).join('')}</div></article>`}
function maRisk(){const d=maCurrent(),locked=maLocked();const section=(type,key,title,addLabel)=>`<form id="maSection-${type}" class="ma-assessment-editor" onsubmit="event.preventDefault();maSaveRiskTemplate('${type}')"><fieldset ${locked?'disabled':''}>${maPanel(title,`<div id="maTemplate-${type}" class="ma-risk-entries">${(d[key].length?d[key]:[{}]).map((r,i)=>maTemplateRow(type,r,i)).join('')}</div><p id="maTemplateError-${type}" class="ma-template-error" role="alert"></p>`,btn(addLabel,`type="button" onclick="maAddTemplateRow('${type}')"`,'','plus')+maSaveStatus(type,d)+`<button type="submit" class="btn primary" aria-label="Lưu ${type==='risk'?'đánh giá rủi ro':'lộ trình pháp lý'}">Lưu</button>`)}</fieldset></form>`;return `<div id="maRiskTemplateForm">${section('risk','risks','Đánh giá các rủi ro pháp lý, phương án xử lý','Thêm rủi ro')}${section('roadmap','roadmap','Lộ trình pháp lý','Thêm công việc')}<div class="actions ma-form-actions"><button type="button" class="btn primary" onclick="maCompleteReview()" ${locked?'disabled':''}>Hoàn thành và gửi phê duyệt</button></div></div>`}

function maAddTemplateRow(type){if(!maEditable()||!['risk','roadmap'].includes(type))return;const body=document.getElementById('maTemplate-'+type);body.insertAdjacentHTML('beforeend',maTemplateRow(type,{},-1));maRenumberTemplate(body);body.lastElementChild.querySelector('textarea').focus()}
function maRenumberTemplate(body){[...body.children].forEach((r,i)=>r.querySelector('.ma-template-number').textContent=String(i+1).padStart(2,'0'))}
function maRemoveTemplateRow(button){if(!maEditable())return;const row=button.closest('[data-template-row]'),body=row.parentElement;row.remove();maRenumberTemplate(body);maRefreshSectionStatus(body.id==='maTemplate-risk'?'risk':'roadmap')}
function maReadTemplate(type,d=maCurrent()){const key=type==='risk'?'risks':'roadmap',rows=[];let invalid=null;document.querySelectorAll('#maTemplate-'+type+' [data-template-row]').forEach(row=>{const values=Object.fromEntries([...row.querySelectorAll('[data-field]')].map(el=>[el.dataset.field,el.value.trim()]));if(!Object.values(values).some(Boolean))return;const missing=Object.keys(values).find(k=>!values[k]&&(type==='risk'||k!=='note'));if(missing)invalid=invalid||row.querySelector('[data-field="'+missing+'"]');rows.push({...d[key][Number(row.dataset.sourceIndex)],...values,aiDraft:false})});return {rows,invalid}}
function maSaveRiskTemplate(type){if(!maEditable()||!['risk','roadmap'].includes(type))return false;const {rows,invalid}=maReadTemplate(type),error=document.getElementById('maTemplateError-'+type);if(invalid){error.textContent=type==='risk'?'Nhập đủ mô tả rủi ro, nguyên nhân và phương án xử lý.':'Nhập công việc và thời gian dự kiến.';invalid.focus();return false}const d=maCurrent(),key=d.projectCode+'/'+d.stage,next=JSON.parse(JSON.stringify(maData));next[key][type==='risk'?'risks':'roadmap']=rows;next[key].report=null;next[key].sectionSavedAt={...next[key].sectionSavedAt,[type]:new Date().toISOString()};next[key].history.unshift({text:'Lưu '+(type==='risk'?'đánh giá rủi ro':'lộ trình pháp lý'),time:new Date().toISOString()});if(!maSaveData(next)){maRefreshSectionStatus(type,true);return false}let index=0;document.querySelectorAll('#maTemplate-'+type+' [data-template-row]').forEach(row=>row.dataset.sourceIndex=[...row.querySelectorAll('[data-field]')].some(el=>el.value.trim())?index++:-1);error.textContent='';maRefreshSectionStatus(type);toast('Đã lưu '+(type==='risk'?'đánh giá rủi ro.':'lộ trình pháp lý.'));return true}
function maReviewHasUnsaved(){const d=maCurrent(),pick=(items,keys)=>items.map(item=>keys.map(k=>(item[k]||'').trim()));for(const g of MA_ASSESSMENT_GROUPS){const box=document.getElementById('maAssessmentItems-'+g.id);if(!box)continue;const rows=[...box.querySelectorAll('.ma-assessment-item')].map(row=>Object.fromEntries([...row.querySelectorAll('[data-column]')].map(el=>[el.dataset.column,el.value.trim()]))).filter(item=>Object.values(item).some(Boolean));if(JSON.stringify(pick(rows,['title','content','legalOpinion','proposal']))!==JSON.stringify(pick(maGetAssessment(d,g.id).items,['title','content','legalOpinion','proposal'])))return true}for(const type of ['risk','roadmap']){const keys=type==='risk'?['title','cause','action']:['title','duration','note'],stored=d[type==='risk'?'risks':'roadmap'].map(r=>type==='roadmap'?{...r,note:maRoadmapNote(r)}:r);if(JSON.stringify(pick(maReadTemplate(type).rows,keys))!==JSON.stringify(pick(stored,keys)))return true}return false}
function maCompleteReview(){if(!maEditable())return;const d=maCurrent();if(document.getElementById('maAssessmentTableForm')&&maReviewHasUnsaved()){toast('Có nội dung chưa lưu. Bấm Lưu tại phần đã chỉnh sửa trước khi gửi phê duyệt.');return}if(!maAssessmentFinished(d)){toast('Hoàn tất và Lưu đánh giá thẩm định của 6 nhóm pháp lý trước khi gửi phê duyệt.');return}if(!d.roadmap.length||d.roadmap.some(r=>!r.title?.trim()||!r.duration?.trim())){toast('Hoàn tất và Lưu lộ trình pháp lý trước khi gửi phê duyệt.');return}if(d.risks.some(r=>!r.title?.trim()||!r.cause?.trim()||!r.action?.trim())){toast('Hoàn tất và Lưu đánh giá rủi ro trước khi gửi phê duyệt.');return}showDrawer('Hoàn thành và gửi phê duyệt',`<form id="maCompleteReviewForm" data-case-key="${esc(d.projectCode+'/'+d.stage)}" onsubmit="maConfirmCompleteReview(event)"><p>Head kiểm tra → GMD phê duyệt.</p>${maTextarea('Comment gửi phê duyệt *','approvalComment',d.approvalComment||'',true)}</form>`,btn('Hủy','type="button" onclick="closeDrawer()"')+'<button type="submit" form="maCompleteReviewForm" class="btn primary">Gửi phê duyệt</button>')}
function maConfirmCompleteReview(event){event.preventDefault();if(!maEditable())return;const form=event.target;if(form.dataset.caseKey!==maCurrent().projectCode+'/'+maCurrent().stage){toast('Yêu cầu đang mở đã thay đổi. Vui lòng mở lại phần gửi phê duyệt.');return}if(!form.reportValidity())return;const comment=String(new FormData(form).get('approvalComment')||'').trim();if(!comment)return;const d=maCurrent(),key=d.projectCode+'/'+d.stage,next=JSON.parse(JSON.stringify(maData));next[key].approvalComment=comment;next[key].report=maReportData(next[key]);if(next[key].revisionReason&&JSON.stringify(next[key].report.sections)===next[key].revisionBaseline){toast('Cần cập nhật nội dung theo yêu cầu hiệu chỉnh trước khi gửi lại.');return}if(maSaveData(next)){closeDrawer();maSubmit()}}

function maRiskForm(proposal={}){if(!maEditable())return;showDrawer('Ghi nhận rủi ro pháp lý',`<form id="maRiskForm" onsubmit="event.preventDefault();maSaveRisk()"><div class="form-grid">${maTextarea('Mô tả rủi ro *','title',proposal.title||'',true)}${maTextarea('Nguyên nhân *','cause',proposal.cause||'',true)}${maTextarea('Phương án xử lý *','action',proposal.action||'',true)}<input type="hidden" name="evidence" value="${esc(proposal.evidence||'')}"></div></form>`,btn('Đóng','onclick="closeDrawer()"')+'<button class="btn primary" type="submit" form="maRiskForm">Lưu</button>')}
function maSaveRisk(){if(!maEditable())return;const f=document.getElementById('maRiskForm');if(!f.reportValidity())return;const v=Object.fromEntries(new FormData(f));for(const k of ['title','cause','action']){v[k]=v[k].trim();if(!v[k])return}if(maUpdate(d=>{d.risks.push(v);d.report=null},'Chuyên viên xác nhận rủi ro và phương án xử lý'))closeDrawer()}
function maReportData(d){return {title:'BÁO CÁO THẨM ĐỊNH PHÁP LÝ DỰ ÁN',template:'NVLG-GMS.PLP-SOP06.F02',project:d.project,stage:d.stage,owner:d.request.owner,ind:d.request.ind,generatedAt:new Date().toISOString(),status:'Bản dự thảo',sections:[{title:'I. Thông tin chung dự án',text:`Dự án: ${d.project}\nGiai đoạn: ${d.stage}\nYêu cầu: ${d.request.title}\nĐịnh hướng đầu tư: ${d.request.orientation}\nChuyên viên: ${d.request.owner}\nĐầu mối IND: ${d.request.ind}`},{title:'II. Hiện trạng hồ sơ pháp lý nhận được',text:d.checks.map(c=>`${c.title}: ${c.status}. ${c.note}${c.indConfirmation?' | IND xác nhận: '+c.indConfirmation.by:''}`).join('\n')+'\nTài liệu: '+d.documents.map(doc=>doc.name).join('; ')},{title:'III. Kết quả thẩm định 6 nhóm pháp lý',text:MA_ASSESSMENT_GROUPS.map(g=>{const a=maGetAssessment(d,g.id);return g.name+' — '+a.conclusion+'\n'+a.items.map((item,i)=>(i+1)+'. Hạng mục: '+item.title+'\nNội dung: '+item.content+'\nÝ kiến pháp lý: '+(item.legalOpinion||'Chưa ghi nhận')+'\nĐề xuất: '+(item.proposal||'Chưa ghi nhận')).join('\n\n')+'\nNhận định: '+a.findings+'\nTài liệu đối chiếu: '+a.evidence.map(id=>d.documents.find(doc=>doc.id===id)?.name||id).join('; ');}).join('\n\n')},{title:'IV. Đánh giá các rủi ro pháp lý, phương án xử lý',text:d.risks.length?d.risks.map((r,i)=>`${i+1}. Mô tả rủi ro: ${r.title}\nNguyên nhân: ${r.cause||'Chưa ghi nhận'}\nPhương án xử lý: ${r.action}`).join('\n\n'):'Chưa ghi nhận rủi ro; không đồng nghĩa dự án không có rủi ro.'},{title:'V. Lộ trình pháp lý',text:d.roadmap.map((r,i)=>`${i+1}. Công việc: ${r.title}\nThời gian dự kiến: ${r.duration}\nGhi chú: ${maRoadmapNote(r)}`).join('\n\n')||'Chưa lập lộ trình.'},{title:'VI. Đánh giá tính khả thi & Kiến nghị',text:'Tính khả thi: '+(d.feasibility||'Chưa đánh giá')+'\nKiến nghị: '+(d.recommendation||'Chưa ghi nhận')}],note:'Bản dựng theo cấu trúc F02 trong nội dung quy trình người dùng cung cấp; chưa phải mẫu F02 gốc đã được xác nhận.'};}
function maReport(){const d=maCurrent();return maPanel('4. Báo cáo thẩm định · F02',`${maSla('report',d.analysisCompleted)}<form id="maConclusionForm" onsubmit="event.preventDefault();maSaveConclusion()"><fieldset ${maLocked()?'disabled':''}><div class="form-grid">${maTextarea('Đánh giá tính khả thi theo định hướng đầu tư *','feasibility',d.feasibility,true)}${maTextarea('Kiến nghị gửi Hội đồng Đầu tư *','recommendation',d.recommendation,true)}</div><button class="btn ma-form-actions" type="submit">Lưu đánh giá & kiến nghị</button></fieldset></form><div class="actions ma-form-actions">${btn('Kết xuất Báo cáo thẩm định',`onclick="maGenerateReport()" ${maLocked()?'disabled':''}`,'primary','file')}${d.report?btn('Word (.docx)','onclick="maDownloadReport(\'docx\')"','','download')+btn('PDF bảo mật','onclick="maDownloadReport(\'pdf\')"','','download'):''}</div>${d.report?maReportPreview(d.report):'<p class="empty">Chưa có báo cáo F02 được tổng hợp.</p>'}`,btn('Gửi kiểm tra / phê duyệt','onclick="maCompleteReview()"','','arrow'));}
function maSaveConclusion(){if(!maEditable())return;const f=$('#maConclusionForm');if(!f.reportValidity())return;const v=Object.fromEntries(new FormData(f));if(!v.feasibility.trim()||!v.recommendation.trim())return;maUpdate(d=>{d.feasibility=v.feasibility.trim();d.recommendation=v.recommendation.trim();d.report=null;},'Lưu tính khả thi và kiến nghị của chuyên viên');}
function maGenerateReport(){if(!maEditable())return;const d=maCurrent();if(!d.request.title){toast('Tiếp nhận yêu cầu trước khi lập báo cáo.');return;}maUpdate(d=>{d.report=maReportData(d);},'Tổng hợp dự thảo F02 từ dữ liệu đã lưu');}
function maReportPreview(report){return `<article class="ma-report-preview"><div class="ma-report-meta"><strong>${esc(report.template)}</strong><span>${esc(report.status)}</span></div><h2>${esc(report.title)}</h2><p>${esc(report.project)} · ${report.stage}</p>${report.sections.map(s=>`<section><h3>${esc(s.title)}</h3><p>${esc(s.text).replace(/\n/g,'<br>')}</p></section>`).join('')}<p class="ma-sla-note">${esc(report.note)}</p></article>`;}
function maSubmit(){const d=maCurrent();if(maLocked())return;const errors=[];if(!d.reviewStarted||!maAssessmentFinished(d))errors.push('chưa hoàn tất và lưu thẩm định 6 nhóm');if(!d.approvalComment?.trim())errors.push('thiếu comment gửi phê duyệt');if(!d.roadmap.length)errors.push('chưa lập lộ trình pháp lý');if(!d.report)errors.push('chưa tổng hợp báo cáo');if(d.revisionReason&&d.report&&JSON.stringify(d.report.sections)===d.revisionBaseline)errors.push('chưa cập nhật theo yêu cầu hiệu chỉnh');if(errors.length){toast(errors.join('; ')+'.');return}if(maUpdate(d=>{maApprovalEvent(d,'submitted',d.request.owner||'Người gửi','Chuyên viên pháp lý',d.approvalComment);d.submitted=new Date().toISOString();d.headChecked=null;d.approvalWorkflow='head-gmd';d.report.status='Chờ Head kiểm tra';d.approvalSubmission={requestId:maRequestCode(d),projectId:maINDIdentity(d).projectId,stage:d.stage,comment:d.approvalComment,submittedAt:d.submitted,report:JSON.parse(JSON.stringify(d.report))}},'Gửi báo cáo và comment cho Head kiểm tra'))maGo('approval')}

function maApprovalReport(d=maCurrent()){return d.approvedReport||d.approvalSubmission?.report||d.report}
function maApprovalEvents(d){if(d.approvalEvents?.length)return [...d.approvalEvents].sort((a,b)=>Date.parse(b.time)-Date.parse(a.time));const events=[];if(d.submitted)events.push({type:'submitted',time:d.submitted,by:d.request.owner||'Người gửi',role:'Chuyên viên pháp lý',comment:d.approvalComment||''});if(d.headChecked)events.push({type:'head-reviewed',time:d.headChecked.time,by:d.headChecked.by||'Head',role:'Head',comment:d.headChecked.comment||''});if(d.approved)events.push({type:'approved',time:d.approved.time,by:d.approved.by||'GMD',role:'GMD',comment:d.approved.comment||''});return events.sort((a,b)=>Date.parse(b.time)-Date.parse(a.time))}
function maApprovalEvent(d,type,by,role,comment,time=new Date().toISOString()){if(!Array.isArray(d.approvalEvents))d.approvalEvents=maApprovalEvents(d);d.approvalEvents.unshift({id:'approval-'+Date.now()+'-'+Math.random().toString(36).slice(2,7),type,by,role,comment,time})}
function maApproval(){const d=maCurrent(),report=maApprovalReport(d),events=maApprovalEvents(d),labels={submitted:'Gửi duyệt','head-reviewed':'Head đã kiểm tra',approved:'Phê duyệt',revision:'Yêu cầu hiệu chỉnh'};return maPanel('Tiến trình phê duyệt',`<div class="ma-approval-attachment">${icon('file')}<div><strong>Báo cáo thẩm định pháp lý dự án</strong><span>${esc(d.project)} · ${esc(maRequestCode(d))} · ${esc(d.stage)}</span><small>${report?'Báo cáo đính kèm hồ sơ phê duyệt':'Báo cáo sẽ được đính kèm khi gửi phê duyệt'}</small></div>${report?btn('Xem báo cáo','type="button" onclick="maViewApprovalReport()"','','file'):''}</div>${d.submitted&&!d.approved?`<div class="actions ma-form-actions ma-approval-toolbar">${btn('Head xác nhận kiểm tra',`onclick="maHeadCheck()" ${!d.submitted||d.headChecked||d.approved?'disabled':''}`,'primary','check')}${btn('GMD phê duyệt',`onclick="maApprove()" ${!d.submitted||!d.headChecked||d.approved?'disabled':''}`,'primary','check')}${btn('Yêu cầu hiệu chỉnh',`onclick="maRevisionForm()" ${!d.submitted||d.approved||d.revisionCount>=1?'disabled':''}`,'','arrow')}</div>`:''}<ol class="ma-approval-timeline">${events.map(event=>{const name=String(event.by||event.role||'Người xử lý'),initials=name.split(/\s+/).filter(Boolean).slice(-2).map(word=>word[0]).join('').toUpperCase();return `<li class="ma-timeline-event ${esc(event.type)}"><div class="ma-timeline-time"><time datetime="${esc(event.time)}">${esc(new Date(event.time).toLocaleString('vi-VN',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'}))}</time><span>${esc(labels[event.type]||'Xử lý')}</span></div><div class="ma-timeline-point" aria-hidden="true"></div><div class="ma-timeline-avatar" aria-hidden="true">${esc(initials)}</div><div class="ma-timeline-content"><strong>${esc(name)}</strong><small>${esc(event.role||'')}</small><p class="ma-timeline-action">${esc({submitted:'Gửi báo cáo cho Head kiểm tra', 'head-reviewed':'Chuyển GMD phê duyệt',approved:'GMD đã phê duyệt báo cáo thẩm định',revision:'Trả lại để cập nhật kết quả thẩm định'}[event.type]||'')}</p>${event.comment?`<p class="ma-timeline-comment"><b>Ý kiến:</b> ${esc(event.comment)}</p>`:''}</div></li>`}).join('')||'<li class="empty">Chưa có tiến trình phê duyệt. Hoàn thành đánh giá và gửi phê duyệt để bắt đầu.</li>'}</ol>`, `<span class="tag ${d.approved?'green':''}">${esc(maStatus(d))}</span>`)}
function maViewApprovalReport(){const report=maApprovalReport();if(!report){toast('Chưa có báo cáo được đính kèm.');return}showDrawer('Báo cáo thẩm định đính kèm',maReportPreview(report),btn('Đóng','type="button" onclick="closeDrawer()"')+btn('Tải Word',`type="button" onclick="maDownloadReport('docx',maApprovalReport())"`,'','download')+btn('Tải PDF',`type="button" onclick="maDownloadReport('pdf',maApprovalReport())"`,'primary','download'))}
function maOpenApprovalProgress(project,stage){if(!maData[project+'/'+stage])return;location.hash=maHash(project,stage,'approval')}

function maHeadCheck(){const d=maCurrent();if(!d.submitted||d.headChecked||d.approved)return;if(maUpdate(d=>{maApprovalEvent(d,'head-reviewed','Head','Head','Đã kiểm tra báo cáo, chuyển GMD xem xét phê duyệt.');d.headChecked={by:'Head',time:new Date().toISOString()};d.report.status='Chờ GMD phê duyệt'},'Head kiểm tra và chuyển GMD phê duyệt'))toast('Head đã kiểm tra. Báo cáo được chuyển GMD phê duyệt.')}

function maRevisionForm(){const d=maCurrent();if(!d.submitted||d.approved||d.revisionCount>=1){toast('Không thể yêu cầu hiệu chỉnh thêm. Ghi nhận họp thống nhất nếu cần.');return;}showDrawer((d.headChecked?'GMD':'Head')+' yêu cầu hiệu chỉnh · lần 1/1',`<form id="maRevisionForm" onsubmit="event.preventDefault();maRequestRevision()">${maTextarea('Nội dung cần hiệu chỉnh *','reason','',true)}</form>`,btn('Đóng','onclick="closeDrawer()"')+'<button class="btn primary" type="submit" form="maRevisionForm">Gửi yêu cầu sửa</button>');}
function maRequestRevision(){const d=maCurrent();if(!d.submitted||d.approved||d.revisionCount>=1)return;const f=$('#maRevisionForm');if(!f.reportValidity())return;const reason=new FormData(f).get('reason').trim();if(!reason)return;closeDrawer();maUpdate(d=>{maApprovalEvent(d,'revision',d.headChecked?'GMD':'Head',d.headChecked?'GMD':'Head',reason);d.revisionCount=1;d.revisionReason=reason;d.revisionBaseline=JSON.stringify(d.report.sections);d.submitted=null;d.headChecked=null;d.report.status='Yêu cầu hiệu chỉnh';},'Yêu cầu hiệu chỉnh báo cáo · lần 1/1');}
function maApprove(){const d=maCurrent();if(!d.submitted||!d.headChecked||d.approved)return;if(maUpdate(d=>{maApprovalEvent(d,'approved','GMD','GMD','Phê duyệt báo cáo thẩm định pháp lý dự án.');d.approved={by:'GMD',time:new Date().toISOString()};d.report.status='Đã phê duyệt';d.approvedReport=JSON.parse(JSON.stringify(d.report))},'GMD phê duyệt kết quả thẩm định; chờ người dùng gửi IND')){toast('Đã phê duyệt. Mở Danh mục yêu cầu để gửi kết quả về IND.');location.hash='#p04'}}

function maMeetingForm(){showDrawer('Ghi nhận họp làm rõ / thống nhất',`<form id="maMeetingForm" onsubmit="event.preventDefault();maSaveMeeting()">${maInput('Thành phần *','people','','text',true)}${maTextarea('Nội dung / kết luận *','notes','',true)}</form>`,btn('Đóng','onclick="closeDrawer()"')+'<button class="btn primary" type="submit" form="maMeetingForm">Lưu biên bản</button>');}
function maSaveMeeting(){const f=$('#maMeetingForm');if(!f.reportValidity())return;const v=Object.fromEntries(new FormData(f));if(!v.people.trim()||!v.notes.trim())return;closeDrawer();maUpdate(d=>{d.supplements.push({kind:'meeting',...v,time:new Date().toISOString()});},'Ghi nhận họp làm rõ / thống nhất: '+v.notes);}
function maHandover(){const d=maCurrent(),identity=maINDIdentity(d);return maPanel('Gửi kết quả về IND',`<dl class="detail-meta"><div><dt>Mã yêu cầu IND</dt><dd>${esc(identity.requestId)}</dd></div><div><dt>Dự án</dt><dd>${esc(d.project)} · ${esc(identity.projectId)}</dd></div><div><dt>Giai đoạn</dt><dd>${esc(d.stage)}</dd></div><div><dt>Trạng thái</dt><dd>${d.handover?esc(d.handover.status):d.approved?'Đã phê duyệt · Chưa gửi IND':'Chờ phê duyệt'}</dd></div></dl><div class="actions ma-form-actions">${btn('Gửi kết quả IND',`onclick="maOpenSendIND('${d.projectCode}','${d.stage}')" ${!d.approved||d.handover?'disabled':''}`,'primary','arrow')}${d.handover?btn('IND xác nhận tiếp nhận',`onclick="maReceiveIND()" ${d.handover.receivedAt?'disabled':''}`):''}<a class="btn" href="#p04">Danh mục yêu cầu</a></div><p class="ma-sla-note">Prototype: thao tác gửi và xác nhận IND được mô phỏng; chưa kết nối API IND.</p>${maDocuments('supplement')}`)}
function maINDIdentity(d){return {requestId:String(d.approvalSubmission?.requestId||d.sourceRequestId||d.request.sourceRequestId||d.request.code||maRequestCode(d)),projectId:String(d.approvalSubmission?.projectId||d.sourceProjectId||d.request.sourceProjectId||d.projectCode)}}
function maOpenSendIND(project,stage){const d=maData[project+'/'+stage];if(!d?.approved||d.handover)return;const id=maINDIdentity(d);showDrawer('Gửi kết quả đã phê duyệt về IND',`<form id="maSendINDForm" onsubmit="maSendApprovedToIND(event,'${esc(project)}','${esc(stage)}')"><dl class="detail-meta"><div><dt>Mã yêu cầu IND</dt><dd>${esc(id.requestId)}</dd></div><div><dt>Dự án</dt><dd>${esc(d.project)}</dd></div><div><dt>Mã dự án IND</dt><dd>${esc(id.projectId)}</dd></div><div><dt>Loại yêu cầu</dt><dd>${esc(d.stage)}</dd></div></dl><p>Kết quả gửi là báo cáo đã được GMD phê duyệt.</p>${maTextarea('Comment gửi IND','comment',d.approvalComment||'')}<p class="note">Prototype: ghi nhận nội dung gửi để trình bày luồng; chưa gửi thực tế qua API IND.</p></form>`,btn('Hủy','type="button" onclick="closeDrawer()"')+'<button type="submit" class="btn primary" form="maSendINDForm">Xác nhận gửi IND</button>')}
function maSendApprovedToIND(event,project,stage){event.preventDefault();const key=project+'/'+stage,d=maData[key];if(!d?.approved||d.handover)return;const identity=maINDIdentity(d),comment=String(new FormData(event.target).get('comment')||'').trim(),time=new Date().toISOString(),report=d.approvedReport||d.report;if(!report||!identity.requestId||!identity.projectId){toast('Thiếu báo cáo hoặc mã yêu cầu, mã dự án IND.');return}const next=JSON.parse(JSON.stringify(maData));next[key].handover={createdAt:time,to:d.request.ind,status:'Đã ghi nhận gửi IND (mô phỏng)',receivedAt:null,mode:'prototype',payload:{sourceSystem:'PLP',targetSystem:'IND',requestId:identity.requestId,projectId:identity.projectId,projectName:d.project,stage:d.stage,correlationId:'PLP-IND-'+project+'-'+stage+'-'+Date.now(),approvedAt:d.approved.time,comment,report:JSON.parse(JSON.stringify(report))}};next[key].history.unshift({text:'Ghi nhận gửi IND mô phỏng theo mã yêu cầu '+identity.requestId+' và dự án '+identity.projectId,time});if(maSaveData(next)){closeDrawer();renderMa();toast('Đã ghi nhận gửi kết quả IND trong prototype.')}}

function maReceiveIND(){const d=maCurrent();if(!d.approved||!d.handover||d.handover.receivedAt)return;maUpdate(d=>{d.handover.receivedAt=new Date().toISOString();d.handover.status='IND đã xác nhận tiếp nhận';},'IND xác nhận đã nhận F02 '+d.stage);}
function maArchive(){const d=maCurrent();return maPanel('Lưu trữ & quản trị hồ sơ',`${maSla('archive',d.handover?.receivedAt)}<dl class="detail-meta"><div><dt>Thành phần bàn giao</dt><dd>Hồ sơ gốc · Checklist F01 · Báo cáo F02 đã duyệt</dd></div><div><dt>Bản cứng</dt><dd>Tối thiểu 03 năm theo nội dung quy trình đã cung cấp</dd></div><div><dt>File scan</dt><dd>Lưu vĩnh viễn theo nội dung quy trình đã cung cấp</dd></div><div><dt>Quy định tham chiếu</dt><dd>NVLG-RPC-REG02 · NVLG-ODD-REG05</dd></div></dl><div class="actions ma-form-actions">${btn('Bàn giao vào Lưu trữ',`onclick="maArchiveCase()" ${!d.handover?.receivedAt||d.archived?'disabled':''}`,'primary','archive')}${d.archived?'<a class="btn" href="#p21">Mở Lưu trữ →</a>':''}</div>${d.archived?`<p class="note">Đã lưu gói hồ sơ ${esc(d.archived.packageId)}. Dữ liệu và tệp của prototype lưu trên trình duyệt này.</p>`:''}<h3 class="ma-section-title">Lịch sử xử lý</h3>${d.history.map(h=>`<div class="activity">${esc(h.text)}<small>${new Date(h.time).toLocaleString('vi-VN')}</small></div>`).join('')||'<p class="empty">Chưa có thao tác được ghi nhận.</p>'}`);}
function maWorkDays(start,days){const date=new Date(start);let count=0;while(count<days){date.setDate(date.getDate()+1);if(![0,6].includes(date.getDay()))count++;}return date;}
function maSla(view,start){const step=MA_STEPS.find(s=>s[0]===view);return `<div class="ma-sla-note">SLA: ${step?.[3]||'Chưa quy định'}${start?` · Bắt đầu ${dateVN(start.slice(0,10))} · Mốc theo dõi ${maWorkDays(start,view==='analysis'?4:1).toLocaleDateString('vi-VN')}`:''}. Lịch minh họa T2–T6; ngày nghỉ và mốc tính chính thức cần xác nhận.</div>`;}

function maDocuments(checkId){const docs=maCurrent().documents.filter(d=>!checkId||d.checkId===checkId);return docs.length?`<div class="ma-document-list">${docs.map(d=>`<button class="record-link" onclick="maOpenDocument('${d.id}')">${esc(d.name)}<span class="record-code">${d.pages.length} trang có nội dung trích xuất</span></button>`).join('')}</div>`:'';}
function maUpload(checkId){if(maBusy)return;if(checkId!=='supplement'&&!maEditable())return;const input=document.createElement('input');input.type='file';input.onchange=()=>{if(input.files[0])maUploadFile(checkId,input.files[0]);};input.click();}
async function maExtractFile(file){
 if(/\.txt$/i.test(file.name))return [{page:1,text:(await file.text()).slice(0,60000)}];
 if(!/\.(pdf|jpe?g|png|webp)$/i.test(file.name))return [];
 const pages=[];let worker=null,pdf=null;
 async function ocr(image){if(!worker){const lib=await loadOCRScript('https://cdn.jsdelivr.net/npm/tesseract.js@5.1.1/dist/tesseract.min.js','Tesseract');worker=await lib.createWorker('vie+eng');}return (await worker.recognize(image)).data.text;}
 try{if(/\.pdf$/i.test(file.name)){const lib=await loadOCRScript('https://cdn.jsdelivr.net/npm/pdfjs-dist@3.11.174/build/pdf.min.js','pdfjsLib');lib.GlobalWorkerOptions.workerSrc='https://cdn.jsdelivr.net/npm/pdfjs-dist@3.11.174/build/pdf.worker.min.js';pdf=await lib.getDocument({data:new Uint8Array(await file.arrayBuffer()),isEvalSupported:false,useSystemFonts:true}).promise;if(pdf.numPages>10)throw new Error('Tách PDF thành tệp tối đa 10 trang cho lần nhận dạng này.');for(let n=1;n<=pdf.numPages;n++){const p=await pdf.getPage(n),items=(await p.getTextContent()).items;let text=items.map(x=>x.str).join(' ');if(text.replace(/\s/g,'').length<30){const v=p.getViewport({scale:1.6}),canvas=document.createElement('canvas');canvas.width=Math.ceil(v.width);canvas.height=Math.ceil(v.height);await p.render({canvasContext:canvas.getContext('2d'),viewport:v}).promise;text=await ocr(canvas);canvas.width=canvas.height=0;}pages.push({page:n,text:text.slice(0,15000)});p.cleanup();}}else pages.push({page:1,text:(await ocr(file)).slice(0,15000)});return pages;}finally{if(worker)await worker.terminate();if(pdf)await pdf.destroy();}
}
async function maUploadFile(checkId,file){
 if(maBusy)return;if(file.size>20*1024*1024){toast('Chọn tệp không quá 20 MB.');return;}
 const route=maRoute(),key=route.project.code+'/'+route.stage;if(checkId!=='supplement'&&maLocked())return;
 if(checkId==='supplement'&&(!maCurrent().approved||maCurrent().archived)){toast('Chỉ ghi nhận bổ sung sau duyệt và trước lưu trữ.');return;}
 maBusy=true;renderMa();const id='MA-DOC-'+Date.now()+'-'+Math.random().toString(36).slice(2,7);
 try{const pages=await maExtractFile(file);await attachmentRequest('readwrite',store=>store.put({id,file}));const next=JSON.parse(JSON.stringify(maData)),d=next[key];if((checkId!=='supplement'&&maLocked(d))||d.archived)throw new Error('Hồ sơ đã chuyển trạng thái; tải lại tại bước phù hợp.');d.documents.push({id,name:file.name,checkId,attachmentId:id,pages,receivedAt:new Date().toISOString()});const check=d.checks.find(c=>c.id===checkId);if(check){check.status='Đã nhận';check.indConfirmation=null;d.report=null;}if(checkId==='supplement')d.supplements.push({kind:'document',name:file.name,time:new Date().toISOString(),status:'Chờ xem xét bổ sung'});d.history.unshift({text:'Tiếp nhận tài liệu: '+file.name,time:new Date().toISOString()});if(!maSaveData(next)){await attachmentRequest('readwrite',s=>s.delete(id));return;}toast('Đã tiếp nhận tài liệu.');}catch(error){await attachmentRequest('readwrite',store=>store.delete(id)).catch(()=>{});toast(error.message||'Chưa tiếp nhận được tài liệu.');}finally{maBusy=false;if(current.gi===1)renderMa();}
}
function maOpenDocument(id,page=1){const doc=maCurrent().documents.find(d=>d.id===id);if(!doc)return;const text=doc.pages.find(p=>p.page===page)?.text||'Tệp chưa có nội dung trích xuất. Tải bản gốc để đối chiếu.';showDrawer(doc.name,`<div class="actions">${doc.pages.map(p=>btn('Trang '+p.page,`onclick="maOpenDocument('${id}',${p.page})"`,'small')).join('')}</div><pre class="aqua-page-text">${esc(text)}</pre>`,btn('Đóng','onclick="closeDrawer()"')+btn('Tải tệp gốc',`onclick="downloadScannedOriginal('${doc.attachmentId}')"`,'primary','download'));}
function maCaptureAIDrafts(d){
 for(const g of MA_ASSESSMENT_GROUPS){const box=document.getElementById('maAssessmentItems-'+g.id);if(!box||box.closest('fieldset')?.disabled)continue;const old=maGetAssessment(d,g.id);const items=[...box.querySelectorAll('.ma-assessment-item')].map((row,i)=>{const values=Object.fromEntries([...row.querySelectorAll('[data-column]')].map(el=>[el.dataset.column,el.value.trim()]));if(!Object.values(values).some(Boolean))return null;return {...old.items.find(item=>item.id===row.dataset.itemId),id:row.dataset.itemId||'draft-'+g.id+'-'+Date.now()+'-'+i,...values}}).filter(Boolean);d.assessments[g.id]={...old,schemaVersion:3,items}}
 for(const [type,key] of [['risk','risks'],['roadmap','roadmap']]){const box=document.getElementById('maTemplate-'+type);if(!box||box.closest('fieldset')?.disabled)continue;d[key]=[...box.querySelectorAll('[data-template-row]')].map(row=>{const values=Object.fromEntries([...row.querySelectorAll('[data-field]')].map(el=>[el.dataset.field,el.value.trim()]));return Object.values(values).some(Boolean)?{...d[key][Number(row.dataset.sourceIndex)],...values}:null}).filter(Boolean)}
}
function maApplyAIResults(d){let added=0;for(const suggestion of d.ai){const group=MA_ASSESSMENT_GROUPS.find(g=>g.name===suggestion.category);if(!group)continue;const sourceKey=[group.id,suggestion.docId,suggestion.title].join('|'),a=maGetAssessment(d,group.id);if(!a.items.some(item=>item.aiSourceKey===sourceKey)){a.items.push({id:'ai-'+group.id+'-'+Date.now()+'-'+added,title:suggestion.title,content:suggestion.content||suggestion.analysis||'',legalOpinion:suggestion.legalOpinion||suggestion.analysis||'',proposal:suggestion.action||'',aiDraft:true,aiSourceKey:sourceKey,evidence:suggestion.docId?[suggestion.docId]:[]});a.schemaVersion=3;a.evidence=[...new Set([...a.evidence,...(suggestion.docId?[suggestion.docId]:[])])];d.assessments[group.id]=a;added++}
 // Unsupported observations remain assessment drafts rather than asserted risks.
 if(!suggestion.docId)continue;
 if(!d.risks.some(item=>item.aiSourceKey===sourceKey))d.risks.push({title:suggestion.title,cause:suggestion.cause||'Cần chuyên viên xác minh nguyên nhân.',action:suggestion.action||'',evidence:suggestion.evidence||'',docId:suggestion.docId,page:suggestion.page,aiDraft:true,aiSourceKey:sourceKey});
 const task=suggestion.work||suggestion.action;if(task&&!d.roadmap.some(item=>item.aiSourceKey===sourceKey))d.roadmap.push({title:task,duration:suggestion.duration||'Chưa xác định — cần xác nhận',note:suggestion.note||'Đề xuất AI từ '+group.name+'. Cần chuyên viên rà soát trước khi sử dụng.',aiDraft:true,aiSourceKey:sourceKey})
 }d.reviewStarted=d.reviewStarted||new Date().toISOString();d.analysisCompleted=null;d.report=null;return added}

function maFillStoredAI(){if(!maEditable()||maBusy)return;const key=maCurrent().projectCode+'/'+maCurrent().stage,next=JSON.parse(JSON.stringify(maData));maCaptureAIDrafts(next[key]);maApplyAIResults(next[key]);next[key].history.unshift({text:'Điền kết quả AI đã phân tích vào bản nháp thẩm định, rủi ro và lộ trình',time:new Date().toISOString()});if(maSaveData(next)){closeDrawer();renderMa();toast('Đã điền kết quả AI vào form và lưu bản nháp.')}}
function maOpenAssessmentAI(){const d=maCurrent();if(!d)return;showDrawer('AI hỗ trợ đánh giá, thẩm định và đề xuất lộ trình',`<div id="maAssessmentAIPanel">${maLocked(d)?'<p class="note">Hồ sơ đang trình duyệt hoặc đã được duyệt. Bạn có thể xem đề xuất AI đã lưu; phân tích mới đang được khóa.</p>':''}${location.protocol==='file:'||location.hostname.endsWith('github.io')?'<p class="note">Bản này chưa kết nối máy chủ AI. Để phân tích hồ sơ, mở ứng dụng qua máy chủ PLP có cấu hình provider.</p>':''}<p class="subtext">Phân tích hồ sơ đã nhận theo 6 nhóm pháp lý. Sau khi phân tích, AI tự điền bản nháp vào thẩm định, rủi ro và lộ trình. Nội dung bạn đã nhập được giữ lại; hãy rà soát và Lưu để xác nhận.</p>${MA_ASSESSMENT_GROUPS.map(g=>`<section class="ma-ai-item"><strong>${esc(g.name)}</strong><p class="subtext">${maAssessmentDocuments(d,g.id).length} tài liệu đã phân loại</p>${d.ai.filter(a=>a.category===g.name).map(a=>`<h4>${esc(a.title)}</h4><p>${esc(a.analysis)}</p><p>${esc(a.evidence||'Chưa đủ tài liệu đối chiếu.')}</p><p><strong>Đề xuất xử lý / lộ trình:</strong> ${esc(a.action)}</p>${a.docId?`<button class="text-link" onclick="maOpenDocument('${esc(a.docId)}',${Number(a.page)||1})">Xem tài liệu · Trang ${Number(a.page)||1}</button>`:''}`).join('')}</section>`).join('')}${maBusy?'<p role="status">AI đang phân tích hồ sơ…</p>':''}</div>`,btn('Đóng','type="button" onclick="closeDrawer()"')+(d.ai.length&&!maLocked(d)?btn('Điền kết quả vào form',`type="button" onclick="maFillStoredAI()" ${maBusy?'disabled':''}`):'')+btn(maBusy?'Đang phân tích…':'Phân tích hồ sơ',`type="button" onclick="maRunAI()" ${maBusy||maLocked()?'disabled':''}`,'primary','book'))}
async function maRunAI(){if(maBusy||!maEditable())return;const d=maCurrent(),key=d.projectCode+'/'+d.stage,documents=d.documents.filter(doc=>doc.checkId!=='kickoff'&&doc.checkId!=='supplement'&&doc.pages.some(p=>p.text.trim()));if(!documents.length){toast('Cần hồ sơ có nội dung chữ hoặc OCR để AI phân tích.');return;}if(location.protocol==='file:'||location.hostname.endsWith('github.io')){toast('Tính năng AI cần chạy qua máy chủ PLP có kết nối provider. Bản public hiện chỉ hỗ trợ giao diện.');return;}maBusy=true;maOpenAssessmentAI();try{const response=await fetch('/api/ma/risk',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({project:d.project,stage:d.stage,documents:documents.map((doc,i)=>({id:'MA-DOC-INPUT-'+i,name:doc.name,pages:doc.pages})),assessments:d.assessments}),signal:AbortSignal.timeout(100000)}),data=await response.json();if(!response.ok)throw new Error(data.error||'AI chưa phản hồi.');const next=JSON.parse(JSON.stringify(maData));if(maLocked(next[key]))throw new Error('Hồ sơ đã chuyển sang trình duyệt. Kết quả AI chưa được áp dụng.');if(!Array.isArray(data.items))throw new Error('AI trả kết quả không đúng định dạng. Vui lòng thử lại.');next[key].ai=data.items.map(item=>({...item,docId:documents.find((doc,i)=>'MA-DOC-INPUT-'+i===item.docId)?.id||''}));const sameCase=maRoute().project?.code+'/'+maRoute().stage===key;if(sameCase)maCaptureAIDrafts(next[key]);maApplyAIResults(next[key]);next[key].history.unshift({text:'AI tự điền bản nháp thẩm định, rủi ro và lộ trình; chờ chuyên viên xác minh',time:new Date().toISOString()});if(!maSaveData(next))return;if(sameCase){if(document.getElementById('maAssessmentAIPanel'))closeDrawer();renderMa();toast('AI đã tự điền và lưu bản nháp thẩm định, rủi ro và lộ trình. Vui lòng rà soát và Lưu để xác nhận.')}}catch(error){toast(error.message||'Chưa kết nối được AI.');}finally{maBusy=false;if(document.getElementById('maAssessmentAIPanel')&&maCurrent()===maData[key])maOpenAssessmentAI();}}
async function maDownloadReport(format,report=maCurrent().report){const d=maCurrent();if(!report)return;if(location.protocol==='file:'){toast('Mở ứng dụng tại http://127.0.0.1:8765 để kết xuất Word/PDF.');return;}try{const response=await fetch('/api/ma/report/'+format,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({report}),signal:AbortSignal.timeout(30000)});if(!response.ok){const e=await response.json();throw new Error(e.error||'Chưa xuất được báo cáo.');}const url=URL.createObjectURL(await response.blob()),link=document.createElement('a');link.href=url;link.download=`F02_${d.projectCode}_${d.stage}.${format}`;link.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}catch(error){toast(error.message);}}
async function maArchiveCase(){
 const d=maCurrent();if(maBusy||!d.approved||!d.handover?.receivedAt||d.archived)return;
 const key=d.projectCode+'/'+d.stage,packageId='MA-'+d.projectCode+'-'+d.stage,attachmentId='ma-package-'+packageId;
 maBusy=true;renderMa();
 try{
 const Zip=await loadOCRScript('https://cdn.jsdelivr.net/npm/jszip@3.10.1/dist/jszip.min.js','JSZip'),zip=new Zip();
 const metadata={report:d.report,checks:d.checks,documents:d.documents,assessments:d.assessments,risks:d.risks,roadmap:d.roadmap,history:d.history};
 zip.file('F01_Checklist.json',JSON.stringify(d.checks,null,2));zip.file('F02_Da_duyet.json',JSON.stringify(d.report,null,2));zip.file('Ho_so_tham_dinh.json',JSON.stringify(metadata,null,2));
 for(const doc of d.documents){const original=await attachmentRequest('readonly',store=>store.get(doc.attachmentId));if(!original?.file)throw new Error('Thiếu tệp gốc '+doc.name+'. Chưa bàn giao lưu trữ.');zip.file('Tai_lieu_goc/'+doc.id+'_'+doc.name.replace(/[\\/:*?"<>|]/g,'_'),original.file);}
 const file=new File([await zip.generateAsync({type:'blob',compression:'DEFLATE'})],packageId+'.zip',{type:'application/zip'});
 await attachmentRequest('readwrite',store=>store.put({id:attachmentId,file}));
 const doc={id:packageId,title:'Hồ sơ đánh giá '+d.stage+' · '+d.project,folderId:'ma-archive-'+d.projectCode,issueDate:new Date().toISOString().slice(0,10),issuer:'PLP / GMD',documentType:'Hồ sơ thẩm định',direction:'Nội bộ',version:'1.0',borrowed:false,demo:false,attachmentId,maPackage:true};
 const nextDocs=[...archiveDocs.filter(x=>x.id!==packageId),doc],next=JSON.parse(JSON.stringify(maData));next[key].archived={packageId,time:new Date().toISOString(),physicalRetention:'Tối thiểu 3 năm',scanRetention:'Vĩnh viễn'};next[key].history.unshift({text:'Bàn giao ZIP gồm F01, F02 đã duyệt và các tệp gốc vào Lưu trữ',time:new Date().toISOString()});
 const previous=localStorage.getItem('plp-archive-v1');localStorage.setItem('plp-archive-v1',JSON.stringify(nextDocs));
 if(!maSaveData(next)){if(previous===null)localStorage.removeItem('plp-archive-v1');else localStorage.setItem('plp-archive-v1',previous);await attachmentRequest('readwrite',store=>store.delete(attachmentId));return;}
 archiveDocs=nextDocs;
 let root=archiveRoots.find(n=>n.id==='ma-archive');if(!root){root={id:'ma-archive',name:'Đánh giá PLDA - M&A',children:[]};prepareArchiveNode(root);archiveRoots.push(root);}
 if(!archiveNodes.has(doc.folderId)){const folder={id:doc.folderId,name:d.project,children:[],sourceLeaf:true};prepareArchiveNode(folder,root);root.children.push(folder);}
 toast('Đã lưu gói hồ sơ và các tệp gốc vào Lưu trữ.');
 }catch(error){await attachmentRequest('readwrite',store=>store.delete(attachmentId)).catch(()=>{});toast(error.message||'Chưa bàn giao được hồ sơ vào Lưu trữ.');}
 finally{maBusy=false;if(current.gi===1)renderMa();}
}
// Restore only the archive metadata/folders belonging to M&A packages after reload.
if(archiveDocs.some(d=>d.maPackage)){let root=archiveRoots.find(n=>n.id==='ma-archive');if(!root){root={id:'ma-archive',name:'Đánh giá PLDA - M&A',children:[]};prepareArchiveNode(root);archiveRoots.push(root);}archiveDocs.filter(d=>d.maPackage).forEach(d=>{if(!archiveNodes.has(d.folderId)){const folder={id:d.folderId,name:d.title.split(' · ').slice(1).join(' · ')||d.title,children:[],sourceLeaf:true};prepareArchiveNode(folder,root);root.children.push(folder);}});}
renderNav();

